using System.Collections.Generic;
using UnityEngine;

namespace Megastructure.EditorTools
{
    /// <summary>
    /// One material to be generated by BatchTools.RebuildAll as Assets/_Game/Materials/M_&lt;id&gt;.mat.
    /// Property values: floats, colours, vectors. Colours are given as LINEAR values; MaterialFactory gamma-encodes plain
    /// (non-[HDR]) Color properties so the shader receives exactly that linear value (Unity converts Color properties
    /// from sRGB in a linear project); [HDR] colours and vectors are written unchanged. At runtime set linear values on
    /// plain Color properties with SetVector, never SetColor. Keywords are not used.
    /// </summary>
    public sealed class RingMaterialDef
    {
        public string Id;
        public string Shader;                      // e.g. "Megastructure/RingCeramic"
        public int RenderQueue = -1;               // -1 = shader default
        public bool EnableInstancing;
        public readonly Dictionary<string, float> Floats = new Dictionary<string, float>();
        public readonly Dictionary<string, Color> Colors = new Dictionary<string, Color>();
        public readonly Dictionary<string, Vector4> Vectors = new Dictionary<string, Vector4>();

        public RingMaterialDef(string id, string shader) { Id = id; Shader = shader; }
        public RingMaterialDef F(string name, float v) { Floats[name] = v; return this; }
        public RingMaterialDef Col(string name, Color linear) { Colors[name] = linear; return this; }
        public RingMaterialDef Vec(string name, Vector4 v) { Vectors[name] = v; return this; }
        public RingMaterialDef Queue(int q) { RenderQueue = q; return this; }
    }

    /// <summary>
    /// Implemented once per owner (one file per builder under Scripts/Editor/MaterialDefs/). RebuildAll discovers all
    /// implementations with TypeCache, creates or updates every material, and fills RingAssets.materials.
    /// A material id must be defined by exactly one owner (RebuildAll fails on duplicates).
    /// </summary>
    public interface IRingMaterialDefs
    {
        IEnumerable<RingMaterialDef> Defs();
    }

    /// <summary>Lead-owned materials (sky and the ceramic family).</summary>
    public sealed class LeadMaterialDefs : IRingMaterialDefs
    {
        public IEnumerable<RingMaterialDef> Defs()
        {
            yield return new RingMaterialDef(RingMat.Sky, "Megastructure/RingSky").F("_DomeRadius", 100f);
            yield return new RingMaterialDef(RingMat.Ceramic, "Megastructure/RingCeramic")
                .Col("_BaseColor", RingPalette.Lin("CeramicWhite")).Col("_JointColor", RingPalette.Lin("CeramicShade"))
                .F("_Smoothness", 0.55f).Vec("_PanelSize", new Vector4(1.2f, 0.6f, 1.2f, 0f)).F("_PanelLine", 0.008f);
            yield return new RingMaterialDef(RingMat.CeramicShade, "Megastructure/RingCeramic")
                .Col("_BaseColor", RingPalette.Lin("CeramicShade")).Col("_JointColor", RingPalette.Lin("CeramicShade") * 0.8f)
                .F("_Smoothness", 0.45f).Vec("_PanelSize", new Vector4(0.6f, 0.6f, 0.6f, 0f)).F("_PanelLine", 0.008f);
            yield return new RingMaterialDef(RingMat.PaleGold, "Megastructure/RingCeramic")
                .Col("_BaseColor", RingPalette.Lin("PaleGold")).Col("_JointColor", RingPalette.Lin("PaleGold") * 0.7f)
                .F("_Smoothness", 0.6f).Vec("_PanelSize", new Vector4(100f, 100f, 100f, 0f)).F("_PanelLine", 0.004f).F("_EdgeWear", 0.9f);
            yield return new RingMaterialDef(RingMat.Metal, "Megastructure/RingCeramic")
                .Col("_BaseColor", RingPalette.Lin("CeramicShade") * 0.62f).Col("_JointColor", RingPalette.Lin("CeramicShade") * 0.4f)
                .F("_Smoothness", 0.6f).Vec("_PanelSize", new Vector4(100f, 100f, 100f, 0f)).F("_PanelLine", 0.004f).F("_EdgeWear", 0.8f);
            yield return new RingMaterialDef(RingMat.PathStrip, "Megastructure/RingCeramic")
                .Col("_BaseColor", RingPalette.Lin("CeramicWhite") * 0.93f).Col("_JointColor", RingPalette.Lin("CeramicShade"))
                .F("_Smoothness", 0.42f).Vec("_PanelSize", new Vector4(1.5f, 1.5f, 1.5f, 0f)).F("_PanelLine", 0.008f);
            yield return new RingMaterialDef(RingMat.Stone, "Megastructure/RingCeramic")
                .Col("_BaseColor", RingPalette.Lin("CeramicShade") * 1.08f).Col("_JointColor", RingPalette.Lin("CeramicShade") * 0.72f)
                .F("_Smoothness", 0.3f).Vec("_PanelSize", new Vector4(0.6f, 0.3f, 0.6f, 0f)).F("_PanelLine", 0.010f);
            yield return new RingMaterialDef(RingMat.Deck, "Megastructure/RingCeramic")
                .Col("_BaseColor", RingPalette.Lin("CeramicWhite")).Col("_JointColor", RingPalette.Lin("CeramicShade"))
                .F("_Smoothness", 0.5f).Vec("_PanelSize", new Vector4(2f, 2f, 2f, 0f)).F("_PanelLine", 0.008f);
        }
    }
}
